import React, { useState, useEffect, useRef } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Video, Phone, PhoneOff, Calendar, User, FileText, CheckCircle, Clock, AlertCircle } from 'lucide-react';

// Mock API base URL - replace with your Flask backend URL
const API_BASE = 'http://localhost:5000/api';

const App = () => {
  const [user, setUser] = useState(null);
  const [view, setView] = useState('login');
  const [consultations, setConsultations] = useState([]);
  const [activeCall, setActiveCall] = useState(null);

  // WebRTC refs
  const localVideoRef = useRef(null);
  const remoteVideoRef = useRef(null);
  const peerConnectionRef = useRef(null);
  const localStreamRef = useRef(null);

  useEffect(() => {
    // Check if user is logged in
    const storedUser = JSON.parse(sessionStorage.getItem('user') || 'null');
    if (storedUser) {
      setUser(storedUser);
      setView(storedUser.role === 'patient' ? 'patient-dashboard' : 'doctor-dashboard');
      loadConsultations(storedUser);
    }
  }, []);

  const loadConsultations = async (currentUser) => {
    try {
      const endpoint = currentUser.role === 'patient' 
        ? `/consultations/patient/${currentUser.id}`
        : `/consultations/doctor/${currentUser.id}`;

      const response = await fetch(API_BASE + endpoint);
      const data = await response.json();
      setConsultations(data);
    } catch (error) {
      console.error('Error loading consultations:', error);
    }
  };

  const LoginForm = () => {
    const [isPatient, setIsPatient] = useState(true);
    const [formData, setFormData] = useState({ email: '', password: '' });

    const handleLogin = async (e) => {
      e.preventDefault();
      const role = isPatient ? 'patient' : 'doctor';

      try {
        const response = await fetch(`${API_BASE}/auth/login`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...formData, role })
        });

        const data = await response.json();
        if (response.ok) {
          setUser(data.user);
          sessionStorage.setItem('user', JSON.stringify(data.user));
          setView(role === 'patient' ? 'patient-dashboard' : 'doctor-dashboard');
        } else {
          alert(data.message || 'Login failed');
        }
      } catch (error) {
        console.error('Login error:', error);
        alert('Login failed. Using demo mode.');
        // Demo mode
        const demoUser = {
          id: isPatient ? 1 : 101,
          name: isPatient ? 'John Doe' : 'Dr. Smith',
          email: formData.email,
          role: role
        };
        setUser(demoUser);
        sessionStorage.setItem('user', JSON.stringify(demoUser));
        setView(role === 'patient' ? 'patient-dashboard' : 'doctor-dashboard');
      }
    };

    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-xl p-8 w-full max-w-md">
          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-16 h-16 bg-blue-600 rounded-full mb-4">
              <Video className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-3xl font-bold text-gray-800">TeleMed Care</h1>
            <p className="text-gray-600 mt-2">Early Readmission Prevention</p>
          </div>

          <div className="flex gap-2 mb-6">
            <button
              onClick={() => setIsPatient(true)}
              className={`flex-1 py-2 px-4 rounded-lg font-medium transition ${
                isPatient ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600'
              }`}
            >
              Patient
            </button>
            <button
              onClick={() => setIsPatient(false)}
              className={`flex-1 py-2 px-4 rounded-lg font-medium transition ${
                !isPatient ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600'
              }`}
            >
              Doctor
            </button>
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
              <input
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder={isPatient ? "patient@example.com" : "doctor@example.com"}
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
              <input
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="••••••••"
                required
              />
            </div>
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 rounded-lg font-medium hover:bg-blue-700 transition"
            >
              Sign In
            </button>
          </form>

          <div className="mt-6 text-center">
            <button
              onClick={() => setView('register')}
              className="text-blue-600 hover:text-blue-700 text-sm font-medium"
            >
              Don't have an account? Register
            </button>
          </div>
        </div>
      </div>
    );
  };

  const RegisterForm = () => {
    const [isPatient, setIsPatient] = useState(true);
    const [formData, setFormData] = useState({
      name: '',
      email: '',
      password: '',
      phone: '',
      specialization: '',
      license: ''
    });

    const handleRegister = async (e) => {
      e.preventDefault();
      const role = isPatient ? 'patient' : 'doctor';

      try {
        const response = await fetch(`${API_BASE}/auth/register`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...formData, role })
        });

        const data = await response.json();
        if (response.ok) {
          alert('Registration successful! Please login.');
          setView('login');
        } else {
          alert(data.message || 'Registration failed');
        }
      } catch (error) {
        console.error('Registration error:', error);
        alert('Registration successful! Please login.');
        setView('login');
      }
    };

    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-xl p-8 w-full max-w-md">
          <h1 className="text-2xl font-bold text-gray-800 mb-6 text-center">Create Account</h1>

          <div className="flex gap-2 mb-6">
            <button
              onClick={() => setIsPatient(true)}
              className={`flex-1 py-2 px-4 rounded-lg font-medium transition ${
                isPatient ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600'
              }`}
            >
              Patient
            </button>
            <button
              onClick={() => setIsPatient(false)}
              className={`flex-1 py-2 px-4 rounded-lg font-medium transition ${
                !isPatient ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600'
              }`}
            >
              Doctor
            </button>
          </div>

          <form onSubmit={handleRegister} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Full Name</label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
              <input
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
              <input
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Phone</label>
              <input
                type="tel"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            {!isPatient && (
              <>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Specialization</label>
                  <input
                    type="text"
                    value={formData.specialization}
                    onChange={(e) => setFormData({ ...formData, specialization: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">License Number</label>
                  <input
                    type="text"
                    value={formData.license}
                    onChange={(e) => setFormData({ ...formData, license: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    required
                  />
                </div>
              </>
            )}
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 rounded-lg font-medium hover:bg-blue-700 transition"
            >
              Register
            </button>
          </form>

          <div className="mt-6 text-center">
            <button
              onClick={() => setView('login')}
              className="text-blue-600 hover:text-blue-700 text-sm font-medium"
            >
              Already have an account? Login
            </button>
          </div>
        </div>
      </div>
    );
  };

  const PatientDashboard = () => {
    const [showBooking, setShowBooking] = useState(false);
    const [bookingForm, setBookingForm] = useState({
      symptoms: '',
      discharged_from: '',
      discharge_date: '',
      medications: '',
      urgency: 'normal'
    });

    const handleBookConsultation = async (e) => {
      e.preventDefault();
      try {
        const response = await fetch(`${API_BASE}/consultations`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            patient_id: user.id,
            ...bookingForm
          })
        });

        if (response.ok) {
          alert('Consultation booked successfully!');
          setShowBooking(false);
          loadConsultations(user);
          setBookingForm({
            symptoms: '',
            discharged_from: '',
            discharge_date: '',
            medications: '',
            urgency: 'normal'
          });
        }
      } catch (error) {
        console.error('Booking error:', error);
        // Demo mode
        setConsultations([...consultations, {
          id: Date.now(),
          status: 'pending',
          ...bookingForm,
          created_at: new Date().toISOString()
        }]);
        setShowBooking(false);
      }
    };

    return (
      <div className="min-h-screen bg-gray-50">
        <nav className="bg-white shadow-sm border-b">
          <div className="max-w-7xl mx-auto px-4 py-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <Video className="w-8 h-8 text-blue-600" />
              <h1 className="text-xl font-bold text-gray-800">TeleMed Care</h1>
            </div>
            <div className="flex items-center gap-4">
              <span className="text-gray-600">{user.name}</span>
              <button
                onClick={() => {
                  setUser(null);
                  sessionStorage.removeItem('user');
                  setView('login');
                }}
                className="px-4 py-2 text-gray-600 hover:text-gray-800"
              >
                Logout
              </button>
            </div>
          </div>
        </nav>

        <div className="max-w-7xl mx-auto px-4 py-8">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-bold text-gray-800">My Consultations</h2>
            <button
              onClick={() => setShowBooking(true)}
              className="bg-blue-600 text-white px-6 py-3 rounded-lg font-medium hover:bg-blue-700 transition flex items-center gap-2"
            >
              <Calendar className="w-5 h-5" />
              Book Consultation
            </button>
          </div>

          {showBooking && (
            <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
              <div className="bg-white rounded-xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                <h3 className="text-xl font-bold text-gray-800 mb-4">Book New Consultation</h3>
                <form onSubmit={handleBookConsultation} className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Symptoms / Concerns
                    </label>
                    <textarea
                      value={bookingForm.symptoms}
                      onChange={(e) => setBookingForm({ ...bookingForm, symptoms: e.target.value })}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      rows="4"
                      placeholder="Describe your symptoms and concerns..."
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Recently Discharged From
                    </label>
                    <input
                      type="text"
                      value={bookingForm.discharged_from}
                      onChange={(e) => setBookingForm({ ...bookingForm, discharged_from: e.target.value })}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      placeholder="Hospital name"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Discharge Date
                    </label>
                    <input
                      type="date"
                      value={bookingForm.discharge_date}
                      onChange={(e) => setBookingForm({ ...bookingForm, discharge_date: e.target.value })}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Current Medications
                    </label>
                    <textarea
                      value={bookingForm.medications}
                      onChange={(e) => setBookingForm({ ...bookingForm, medications: e.target.value })}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      rows="3"
                      placeholder="List your current medications..."
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Urgency Level
                    </label>
                    <select
                      value={bookingForm.urgency}
                      onChange={(e) => setBookingForm({ ...bookingForm, urgency: e.target.value })}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    >
                      <option value="normal">Normal</option>
                      <option value="urgent">Urgent</option>
                      <option value="emergency">Emergency</option>
                    </select>
                  </div>
                  <div className="flex gap-3 pt-4">
                    <button
                      type="submit"
                      className="flex-1 bg-blue-600 text-white py-3 rounded-lg font-medium hover:bg-blue-700 transition"
                    >
                      Book Consultation
                    </button>
                    <button
                      type="button"
                      onClick={() => setShowBooking(false)}
                      className="flex-1 bg-gray-200 text-gray-700 py-3 rounded-lg font-medium hover:bg-gray-300 transition"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          <div className="grid gap-4">
            {consultations.length === 0 ? (
              <div className="bg-white rounded-lg p-8 text-center">
                <Calendar className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500">No consultations yet. Book your first consultation!</p>
              </div>
            ) : (
              consultations.map((consultation) => (
                <div key={consultation.id} className="bg-white rounded-lg p-6 shadow-sm border">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${
                          consultation.status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                          consultation.status === 'accepted' ? 'bg-green-100 text-green-700' :
                          consultation.status === 'completed' ? 'bg-blue-100 text-blue-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {consultation.status === 'pending' && <Clock className="w-4 h-4 inline mr-1" />}
                          {consultation.status === 'accepted' && <CheckCircle className="w-4 h-4 inline mr-1" />}
                          {consultation.status}
                        </span>
                        {consultation.urgency === 'urgent' && (
                          <span className="px-3 py-1 rounded-full text-sm font-medium bg-orange-100 text-orange-700">
                            <AlertCircle className="w-4 h-4 inline mr-1" />
                            Urgent
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-gray-500">
                        Booked: {new Date(consultation.created_at).toLocaleDateString()}
                      </p>
                    </div>
                    {consultation.status === 'accepted' && (
                      <button
                        onClick={() => startCall(consultation)}
                        className="bg-green-600 text-white px-4 py-2 rounded-lg font-medium hover:bg-green-700 transition flex items-center gap-2"
                      >
                        <Video className="w-4 h-4" />
                        Join Call
                      </button>
                    )}
                  </div>
                  <div className="space-y-2">
                    <p className="text-gray-700"><strong>Symptoms:</strong> {consultation.symptoms}</p>
                    <p className="text-gray-700"><strong>Discharged from:</strong> {consultation.discharged_from}</p>
                    <p className="text-gray-700"><strong>Discharge date:</strong> {consultation.discharge_date}</p>
                    {consultation.medications && (
                      <p className="text-gray-700"><strong>Medications:</strong> {consultation.medications}</p>
                    )}
                    {consultation.doctor_name && (
                      <p className="text-gray-700"><strong>Doctor:</strong> {consultation.doctor_name}</p>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    );
  };

  const DoctorDashboard = () => {
    const [selectedConsultation, setSelectedConsultation] = useState(null);

    const handleAcceptConsultation = async (consultationId) => {
      try {
        const response = await fetch(`${API_BASE}/consultations/${consultationId}/accept`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ doctor_id: user.id })
        });

        if (response.ok) {
          loadConsultations(user);
          alert('Consultation accepted!');
        }
      } catch (error) {
        console.error('Accept error:', error);
        // Demo mode
        setConsultations(consultations.map(c => 
          c.id === consultationId ? { ...c, status: 'accepted', doctor_id: user.id } : c
        ));
      }
    };

    return (
      <div className="min-h-screen bg-gray-50">
        <nav className="bg-white shadow-sm border-b">
          <div className="max-w-7xl mx-auto px-4 py-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <Video className="w-8 h-8 text-blue-600" />
              <h1 className="text-xl font-bold text-gray-800">TeleMed Care - Doctor Portal</h1>
            </div>
            <div className="flex items-center gap-4">
              <span className="text-gray-600">{user.name}</span>
              <button
                onClick={() => {
                  setUser(null);
                  sessionStorage.removeItem('user');
                  setView('login');
                }}
                className="px-4 py-2 text-gray-600 hover:text-gray-800"
              >
                Logout
              </button>
            </div>
          </div>
        </nav>

        <div className="max-w-7xl mx-auto px-4 py-8">
          <h2 className="text-2xl font-bold text-gray-800 mb-6">Consultation Requests</h2>

          <div className="grid gap-4">
            {consultations.length === 0 ? (
              <div className="bg-white rounded-lg p-8 text-center">
                <FileText className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500">No consultation requests at the moment.</p>
              </div>
            ) : (
              consultations.map((consultation) => (
                <div key={consultation.id} className="bg-white rounded-lg p-6 shadow-sm border">
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <User className="w-5 h-5 text-gray-600" />
                        <h3 className="text-lg font-semibold text-gray-800">
                          Patient #{consultation.patient_id}
                        </h3>
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${
                          consultation.status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                          consultation.status === 'accepted' ? 'bg-green-100 text-green-700' :
                          consultation.status === 'completed' ? 'bg-blue-100 text-blue-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {consultation.status}
                        </span>
                        {consultation.urgency === 'urgent' && (
                          <span className="px-3 py-1 rounded-full text-sm font-medium bg-orange-100 text-orange-700">
                            <AlertCircle className="w-4 h-4 inline mr-1" />
                            Urgent
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-gray-500">
                        Requested: {new Date(consultation.created_at).toLocaleString()}
                      </p>
                    </div>
                    <div className="flex gap-2">
                      {consultation.status === 'pending' && (
                        <button
                          onClick={() => handleAcceptConsultation(consultation.id)}
                          className="bg-blue-600 text-white px-4 py-2 rounded-lg font-medium hover:bg-blue-700 transition flex items-center gap-2"
                        >
                          <CheckCircle className="w-4 h-4" />
                          Accept
                        </button>
                      )}
                      {consultation.status === 'accepted' && consultation.doctor_id === user.id && (
                        <button
                          onClick={() => startCall(consultation)}
                          className="bg-green-600 text-white px-4 py-2 rounded-lg font-medium hover:bg-green-700 transition flex items-center gap-2"
                        >
                          <Video className="w-4 h-4" />
                          Start Call
                        </button>
                      )}
                      <button
                        onClick={() => setSelectedConsultation(selectedConsultation?.id === consultation.id ? null : consultation)}
                        className="bg-gray-200 text-gray-700 px-4 py-2 rounded-lg font-medium hover:bg-gray-300 transition"
                      >
                        {selectedConsultation?.id === consultation.id ? 'Hide' : 'View'} Details
                      </button>
                    </div>
                  </div>

                  {selectedConsultation?.id === consultation.id && (
                    <div className="mt-4 pt-4 border-t space-y-3">
                      <div className="bg-gray-50 p-4 rounded-lg">
                        <h4 className="font-semibold text-gray-800 mb-2">Symptoms & Concerns</h4>
                        <p className="text-gray-700">{consultation.symptoms}</p>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <p className="text-sm font-medium text-gray-600">Discharged From</p>
                          <p className="text-gray-800">{consultation.discharged_from}</p>
                        </div>
                        <div>
                          <p className="text-sm font-medium text-gray-600">Discharge Date</p>
                          <p className="text-gray-800">{consultation.discharge_date}</p>
                        </div>
                      </div>
                      {consultation.medications && (
                        <div className="bg-gray-50 p-4 rounded-lg">
                          <h4 className="font-semibold text-gray-800 mb-2">Current Medications</h4>
                          <p className="text-gray-700">{consultation.medications}</p>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    );
  };

  const startCall = async (consultation) => {
    setActiveCall(consultation);
    setView('video-call');

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      localStreamRef.current = stream;
      if (localVideoRef.current) {
        localVideoRef.current.srcObject = stream;
      }
    } catch (error) {
      console.error('Error accessing media devices:', error);
      alert('Please allow camera and microphone access to start the call.');
    }
  };

  const endCall = () => {
    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach(track => track.stop());
    }
    if (peerConnectionRef.current) {
      peerConnectionRef.current.close();
    }
    setActiveCall(null);
    setView(user.role === 'patient' ? 'patient-dashboard' : 'doctor-dashboard');
  };

  const VideoCallRoom = () => {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col">
        <div className="bg-gray-800 px-4 py-3 flex justify-between items-center">
          <div className="text-white">
            <h2 className="font-semibold">Consultation with {user.role === 'patient' ? 'Doctor' : `Patient #${activeCall?.patient_id}`}</h2>
            <p className="text-sm text-gray-400">Session ID: {activeCall?.id}</p>
          </div>
          <button
            onClick={endCall}
            className="bg-red-600 hover:bg-red-700 text-white px-6 py-2 rounded-lg flex items-center gap-2 transition"
          >
            <PhoneOff className="w-5 h-5" />
            End Call
          </button>
        </div>

        <div className="flex-1 grid grid-cols-2 gap-4 p-4">
          <div className="relative bg-gray-800 rounded-lg overflow-hidden">
            <video
              ref={localVideoRef}
              autoPlay
              muted
              playsInline
              className="w-full h-full object-cover"
            />
            <div className="absolute bottom-4 left-4 bg-black bg-opacity-50 text-white px-3 py-1 rounded">
              You
            </div>
          </div>

          <div className="relative bg-gray-800 rounded-lg overflow-hidden flex items-center justify-center">
            <video
              ref={remoteVideoRef}
              autoPlay
              playsInline
              className="w-full h-full object-cover"
            />
            <div className="absolute bottom-4 left-4 bg-black bg-opacity-50 text-white px-3 py-1 rounded">
              {user.role === 'patient' ? 'Doctor' : 'Patient'}
            </div>
            <div className="absolute inset-0 flex items-center justify-center">
              <p className="text-gray-400">Waiting for other participant...</p>
            </div>
          </div>
        </div>

        <div className="bg-gray-800 px-4 py-4">
          <div className="max-w-4xl mx-auto">
            <h3 className="text-white font-semibold mb-2">Consultation Notes</h3>
            <textarea
              className="w-full px-4 py-2 bg-gray-700 text-white rounded-lg border border-gray-600 focus:border-blue-500 focus:outline-none"
              rows="3"
              placeholder="Add notes during consultation..."
            />
          </div>
        </div>
      </div>
    );
  };

  return (
    <>
      {view === 'login' && <LoginForm />}
      {view === 'register' && <RegisterForm />}
      {view === 'patient-dashboard' && <PatientDashboard />}
      {view === 'doctor-dashboard' && <DoctorDashboard />}
      {view === 'video-call' && <VideoCallRoom />}
    </>
  );
};

export default App;
